export type Testimonial = {
  name: string;
  role: string;
  title: string;
  quote: string;
  gender: "male" | "female";
};

export function testimonialAvatar(t: Testimonial, index: number): string {
  let n = 0;
  for (let i = 0; i < index; i++) {
    if (TESTIMONIALS[i].gender === t.gender) n++;
  }
  const prefix = t.gender === "female" ? "f" : "m";
  return `/images/avatars/${prefix}-${String(n).padStart(2, "0")}.jpg`;
}

